WITH target_routes AS ( /* Optimization 1: Moving massive IN clause to a CTE to prevent internal engine errors */ SELECT CAST(s AS INT) as src_id, CAST(d AS INT) as dest_id FROM (VALUES (122, 123), (123, 122), (123, 141), (124, 122), (122, 124), (124, 134), (122, 71756), (757, 733), (71756, 122), (130, 624), (74820, 74694), (624, 130), (74694, 74820), (130, 309), (122, 216), (124, 123), (134, 122), (130, 575), (124, 462), (123, 124), (462, 124), (122, 71929), (130, 641), (575, 130), (141, 126), (130, 1476), (233, 123), (74661, 122), (641, 130), (248, 134), (126, 141), (122, 995), (130, 361), (995, 122), (71425, 122), (309, 462), (361, 130), (1476, 130), (65976, 130), (122, 95218), (551, 473), (130, 95083), (130, 311), (141, 71929), (624, 124), (313, 551), (95218, 122), (1514, 733), (74701, 79589), (71929, 141), (1290, 733), (123, 504), (122, 78796), (470, 1169), (123, 506), (1382, 130), (733, 1290), (71756, 123), (1437, 733), (624, 361), (70015, 777), (130, 1384), (74701, 93059), (313, 94152), (733, 1437), (361, 624), (70024, 83760), (1384, 130), (122, 923), (130, 65907), (309, 575), (93947, 70014), (575, 309), (1443, 807), (807, 1290), (624, 444), (130, 65859), (833, 777), (646, 130), (1429, 1290), (130, 622), (70015, 833), (122, 65930), (1429, 777), (629, 130), (1290, 1429), (141, 124), (622, 130), (70015, 1290), (777, 1429) ) AS t(s, d) ), event_summary AS ( SELECT mri_session_id, CAST(src_id AS INT) AS src_id, CAST(dest_id AS INT) AS dest_id, MAX(CASE WHEN event_group = 'great_india_sales' AND event_name = 'India_sale_section' AND event_value = 'viewed' THEN 1 ELSE 0 END) as is_viewed, MAX(CASE WHEN event_group = 'great_india_sales' AND event_name = 'India_sale_section' AND event_value IN ('clicked', 'view_all_clicked') THEN 1 ELSE 0 END) as is_clicked, MAX(CASE WHEN event_group = 'srp_click_event' AND event_name = 'Contextual Filters' AND event_value = 'Discover Bharat Sale' THEN 1 ELSE 0 END) as is_contextual FROM user_interaction.ui_ux_events WHERE __time >= TIMESTAMP '2026-01-14 18:30:00' AND __time < TIMESTAMP '2026-01-22 18:30:00' AND header_bu = 'BUS' AND header_country = 'IND' AND event_src = 'Android' GROUP BY 1, 2, 3 ), offer_tuple AS ( SELECT DISTINCT mri_session_id, route_id, src_id, dest_id FROM "user_interaction"."search_route_details" WHERE __time >= TIMESTAMP '2026-01-14 18:30:00' AND __time < TIMESTAMP '2026-01-22 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND campaign_id LIKE '%MULSTL_DBIND%' AND country = 'IND' ), srp_deduped AS ( SELECT CAST(DATE_TRUNC('day', DATE_ADD('minute', 330, s."__time")) AS DATE) AS doi, s.mri_session_id, s.route_id, s.rb_user_id, s.user_type, s.os, s.channel, s.src_id, s.dest_id, rm.region, CASE WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 0 AND HOUR(DATE_ADD('minute', 330, s."__time")) >= 17 THEN '0. LMB Same Day' WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 0 THEN '0. non-LMB Same Day' WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 1 THEN '1. DBD 1' WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) = 2 THEN '2. DBD 2' WHEN date_diff('day', DATE(DATE_ADD('minute', 330, s."__time")), s.doj) > 2 THEN '3. DBD 2+' ELSE 'NA' END AS search_day, CASE WHEN ot.route_id IS NOT NULL AND ot.mri_session_id IS NOT NULL THEN 'Offer Tuple' ELSE 'non-Offer Tuple' END AS tuple_type, CASE WHEN ot_sd.src_id IS NOT NULL THEN 'bharat_sds dynamic' ELSE 'Other SDs' END AS route_type, CASE WHEN tr.src_id IS NOT NULL AND tr.dest_id IS NOT NULL THEN 'Target SDs' ELSE 'non-Target SDs' END AS target_route, CASE WHEN ev.is_clicked = 1 THEN 'Card Interacted sessions' WHEN ev.is_viewed = 1 THEN 'Viewed but not interacted sessions' ELSE 'Regular session' END AS section_interaction, CASE WHEN ev.is_contextual = 1 THEN 'contextual_filtered_sessions' ELSE 'non-contextual_filtered_sessions' END AS contextual_filter_interaction FROM "user_interaction"."search_route_details" s LEFT JOIN target_routes tr ON s.src_id = tr.src_id AND s.dest_id = tr.dest_id /* Join replaces massive IN clause */ LEFT JOIN "lis"."config_locations" rm ON rm.id = s.src_id LEFT JOIN event_summary ev ON s.mri_session_id = ev.mri_session_id AND s.src_id = ev.src_id AND s.dest_id = ev.dest_id LEFT JOIN offer_tuple ot ON s.mri_session_id = ot.mri_session_id AND s.route_id = ot.route_id LEFT JOIN (SELECT DISTINCT src_id, dest_id FROM offer_tuple) ot_sd ON s.src_id = ot_sd.src_id AND s.dest_id = ot_sd.dest_id WHERE s.__time >= TIMESTAMP '2026-01-14 18:30:00' AND s.__time < TIMESTAMP '2026-01-22 18:30:00' AND s.channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND s.country = 'IND' AND s.status = 200 ), sl_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id, MAX(cmp_discount_seats) cmp_discount_seats FROM "user_interaction"."seat_layout_details" WHERE __time >= TIMESTAMP '2026-01-14 18:30:00' AND __time < TIMESTAMP '2026-01-22 18:30:00' AND channel IN ('MOBILE_APP', 'MOBILE_WEB', 'WEB_DIRECT') AND country = 'IND' GROUP BY 1,2 ), mpax_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."cust_info_details" WHERE __time >= TIMESTAMP '2026-01-14 18:30:00' AND __time < TIMESTAMP '2026-01-22 18:30:00' GROUP BY 1,2 ), tco_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."create_order_details" WHERE __time >= TIMESTAMP '2026-01-14 18:30:00' AND __time < TIMESTAMP '2026-01-22 18:30:00' GROUP BY 1,2 ), orderinfo_deduped AS ( SELECT mri_session_id, route_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."order_info_details" WHERE __time >= TIMESTAMP '2026-01-14 18:30:00' AND __time < TIMESTAMP '2026-01-22 18:30:00' GROUP BY 1,2 ), addpay_deduped AS ( SELECT mri_session_id, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."make_payment_details" WHERE __time >= TIMESTAMP '2026-01-14 18:30:00' AND __time < TIMESTAMP '2026-01-22 18:30:00' GROUP BY 1 ), confirm_deduped AS ( SELECT mri_session_id, route_id, tin, MAX(rb_user_id) as rb_user_id FROM "user_interaction"."confirm_order_details" WHERE __time >= TIMESTAMP '2026-01-14 18:30:00' AND __time < TIMESTAMP '2026-01-22 18:30:00' AND status = 200 AND tin IS NOT NULL AND tin NOT IN ('', 'null') GROUP BY 1,2,3 ) SELECT -- CASE WHEN srp.doi >= DATE '2026-01-01' AND srp.doi < DATE '2026-01-07' THEN '0. Jan 01 to Jan 06' -- WHEN srp.doi >= DATE '2026-01-08' AND srp.doi < DATE '2026-01-15' THEN '1. Jan 08 to Jan 14' -- WHEN srp.doi >= DATE '2026-01-15' AND srp.doi < DATE '2026-01-23' THEN '2. Jan 15 to Jan 22' -- WHEN srp.doi >= DATE '2026-01-23' AND srp.doi < DATE '2026-01-27' THEN '3. Jan 23 to Jan 26' -- ELSE ('4. ' || CAST(srp.doi AS VARCHAR)) END AS period, srp.doi, srp.search_day, -- 'Any DBD' search_day, UPPER(srp.user_type) as user_type, srp.route_type, srp.target_route, -- 'Target Route' AS route_type, CASE WHEN srp.os IS NULL THEN srp.channel ELSE srp.os END AS saleschannel, -- srp.tuple_type, 'Overall' AS tuple_type, -- CAST(srp.src_id AS VARCHAR) ||'-'|| CAST(srp.dest_id AS VARCHAR) AS SD_ID, -- (src.location_name ||'-'|| dest.location_name) AS route, -- srp.region, -- CASE WHEN srp.route_type NOT IN ('Other SDs') THEN (CAST(srp.src_id AS VARCHAR) ||'-'|| CAST(srp.dest_id AS VARCHAR)) ELSE srp.route_type END AS SD_ID, -- CASE WHEN srp.route_type NOT IN ('Other SDs') THEN (src.location_name ||'-'|| dest.location_name) ELSE srp.route_type END AS route, -- CASE WHEN srp.route_type NOT IN ('Other SDs') THEN srp.region ELSE 'Overall' END AS region, /* Aggregates */ COUNT(DISTINCT srp.mri_session_id) AS srpload, COUNT(DISTINCT sl.mri_session_id) AS slload, COUNT(DISTINCT pax.mri_session_id) AS paxload, COUNT(DISTINCT tco.mri_session_id) AS tcoload, COUNT(DISTINCT oi.mri_session_id) AS orderinfoload, COUNT(DISTINCT ap.mri_session_id) AS addpay_click, COUNT(DISTINCT conf.mri_session_id) AS confirmsession, COUNT(DISTINCT conf.tin) AS tin FROM srp_deduped srp -- LEFT JOIN "lis"."config_locations" src ON srp.src_id = src.id -- LEFT JOIN "lis"."config_locations" dest ON srp.dest_id = dest.id LEFT JOIN sl_deduped sl ON srp.mri_session_id = sl.mri_session_id AND srp.route_id = sl.route_id LEFT JOIN mpax_deduped pax ON srp.mri_session_id = pax.mri_session_id AND srp.route_id = pax.route_id LEFT JOIN tco_deduped tco ON srp.mri_session_id = tco.mri_session_id AND srp.route_id = tco.route_id LEFT JOIN orderinfo_deduped oi ON srp.mri_session_id = oi.mri_session_id AND srp.route_id = oi.route_id LEFT JOIN addpay_deduped ap ON oi.mri_session_id = ap.mri_session_id LEFT JOIN confirm_deduped conf ON srp.mri_session_id = conf.mri_session_id AND srp.route_id = conf.route_id GROUP BY 1,2,3,4,5,6 ,7 -- ,8,9 ORDER BY 1, 2, 4, 3 DESC;
